# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">İMRAN AİLESİ, HZ. MERYEM VE HZ. İSA\'NIN DOĞUMU</text>\n  <!-- Kutu 1: Imran Ailesi -->\n  <rect x="20" y="45" width="210" height="195" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="125" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e40af">1. İMRAN AİLESİ</text>\n  <rect x="34" y="82" width="182" height="44" rx="6" fill="#dbeafe"/>\n  <text x="125" y="100" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e3a8a">Âl-i İmrân Suresi, 33-37</text>\n  <text x="125" y="117" text-anchor="middle" font-size="10.5" fill="#1d4ed8">Hanne\'nin Beytülmakdis Adağı</text>\n  <text x="34" y="148" font-size="11" fill="#1e3a8a">• Annesi Hanne, doğacak</text>\n  <text x="42" y="164" font-size="11" fill="#1e3a8a">çocuğunu mabede adadı.</text>\n  <text x="34" y="186" font-size="11" fill="#1e3a8a">• Hz. Meryem\'in bakımını</text>\n  <text x="42" y="202" font-size="11" fill="#1e3a8a">ve eğitimini Hz. Zekeriyya</text>\n  <text x="42" y="218" font-size="11" fill="#1e3a8a">(as) üstlendi.</text>\n  <!-- Kutu 2: Mucizevi Dogum -->\n  <rect x="245" y="45" width="210" height="195" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="350" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#92400e">2. İLAHİ MÜJDE VE DOĞUM</text>\n  <rect x="259" y="82" width="182" height="44" rx="6" fill="#fde68a"/>\n  <text x="350" y="100" text-anchor="middle" font-size="11" font-weight="bold" fill="#78350f">Âl-i İmrân Suresi, 42-47</text>\n  <text x="350" y="117" text-anchor="middle" font-size="10.5" fill="#92400e">"Ol!" (Kün) İradesiyle Yaratılış</text>\n  <text x="259" y="148" font-size="11" fill="#78350f">• Hz. İsa\'nın yaratılışı Allah</text>\n  <text x="267" y="164" font-size="11" fill="#78350f">katında Hz. Âdem\'in topraktan</text>\n  <text x="267" y="180" font-size="11" fill="#78350f">yaratılışı gibidir (Âl-i İmrân, 59).</text>\n  <text x="259" y="202" font-size="11" fill="#78350f">• Lakabı: Mesih ve Kelimetullah.</text>\n  <!-- Kutu 3: Besikte Konusma -->\n  <rect x="470" y="45" width="210" height="195" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="575" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#166534">3. BEŞİKTE KONUŞMASI</text>\n  <rect x="484" y="82" width="182" height="44" rx="6" fill="#dcfce7"/>\n  <text x="575" y="100" text-anchor="middle" font-size="11" font-weight="bold" fill="#14532d">Meryem Suresi, 30-36</text>\n  <text x="575" y="117" text-anchor="middle" font-size="10.5" fill="#166534">"Şüphesiz ben Allah\'ın kuluyum."</text>\n  <text x="484" y="148" font-size="11" fill="#14532d">• Beşikteyken konuşarak</text>\n  <text x="492" y="164" font-size="11" fill="#14532d">annesini iftiradan temize çıkardı.</text>\n  <text x="484" y="186" font-size="11" fill="#14532d">• Kendisine İncil verileceğini,</text>\n  <text x="492" y="202" font-size="11" fill="#14532d">namaz ve zekâtla emrolunan</text>\n  <text x="492" y="218" font-size="11" fill="#14532d">bir kul olduğunu bildirdi.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">HZ. İSA\'NIN TEBLİĞİ, MUCİZELERİ VE HAVARİLER</text>\n  <!-- Sol: Toplum ve Teblig -->\n  <rect x="25" y="42" width="315" height="202" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="182" y="65" text-anchor="middle" font-size="13" font-weight="bold" fill="#6b21a8">GÖNDERİLDİĞİ TOPLUM VE MİSYONU</text>\n  <text x="40" y="90" font-size="11.5" fill="#581c87">• Bölge: Roma idaresindeki Filistin (İsrailoğulları).</text>\n  <text x="40" y="112" font-size="11.5" fill="#581c87">• Sorunlar: Şekilci dindarlık, faiz, zulüm, maddeci</text>\n  <text x="50" y="128" font-size="11.5" fill="#581c87">anlayış ve tevhid bilincinin zayıflaması.</text>\n  <rect x="40" y="140" width="285" height="44" rx="6" fill="#f3e8ff" stroke="#a855f7"/>\n  <text x="182" y="158" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#581c87">Saf Suresi, 6. Ayet</text>\n  <text x="182" y="175" text-anchor="middle" font-size="11" fill="#6b21a8">Tevrat\'ı tasdik ve "Ahmet" (Hz. Muhammed) müjdesi</text>\n  <text x="40" y="205" font-size="11.5" font-weight="bold" fill="#7e22ce">• Havariler (Âl-i İmrân, 52): Hz. İsa\'ya iman edip</text>\n  <text x="50" y="222" font-size="11.5" fill="#581c87">"Biz Allah\'ın yardımcılarıyız" diyen samimi dostları.</text>\n  <!-- Sag: Mucizeler -->\n  <rect x="360" y="42" width="315" height="202" rx="10" fill="#fff7ed" stroke="#ea580c" stroke-width="2"/>\n  <text x="517" y="65" text-anchor="middle" font-size="13" font-weight="bold" fill="#9a3412">MUCİZELERİ (MÂİDE, 110-115)</text>\n  <text x="378" y="92" font-size="11.5" fill="#7c2d12">1. Beşikte bebekken konuşması (Rûhu\'l-Kudüs desteği).</text>\n  <text x="378" y="114" font-size="11.5" fill="#7c2d12">2. Çamurdan yaptığı kuş şekline üfleyince canlanması.</text>\n  <text x="378" y="136" font-size="11.5" fill="#7c2d12">3. Doğuştan körleri ve alaca hastalarını iyileştirmesi.</text>\n  <text x="378" y="158" font-size="11.5" fill="#7c2d12">4. Allah\'ın izniyle ölüleri diriltmesi.</text>\n  <text x="378" y="180" font-size="11.5" fill="#7c2d12">5. Evlerde yenilen ve saklanan şeyleri haber vermesi.</text>\n  <rect x="378" y="194" width="280" height="38" rx="6" fill="#ffedd5"/>\n  <text x="518" y="211" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#9a3412">Ortak Vurgu: "Allah\'ın izniyle (bi-iznillâh)"</text>\n  <text x="518" y="226" text-anchor="middle" font-size="11" fill="#7c2d12">Mucizelerin gerçek sahibi Yüce Allah\'tır.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">HZ. İSA SONRASI İNANÇ DEĞİŞİMLERİ VE KUR\'AN\'IN TEVHİD VURGUSU</text>\n  <!-- Sol: Kur\'an\'a Gore Hakikat -->\n  <rect x="25" y="42" width="315" height="202" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="182" y="65" text-anchor="middle" font-size="13" font-weight="bold" fill="#166534">KUR\'AN\'DA HZ. İSA GERÇEĞİ</text>\n  <rect x="42" y="78" width="280" height="46" rx="6" fill="#dcfce7" stroke="#22c55e"/>\n  <text x="182" y="96" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#14532d">Nisâ Suresi, 157-158</text>\n  <text x="182" y="114" text-anchor="middle" font-size="11" fill="#166534">Çarmıha gerilmedi; Allah katına yükseltildi.</text>\n  <text x="42" y="146" font-size="11.5" fill="#14532d">• Mâide, 72-73: Teslis (üçleme) inancı reddedilir.</text>\n  <text x="42" y="168" font-size="11.5" fill="#14532d">• Mâide, 116-117: Hz. İsa kendisinin ve annesinin</text>\n  <text x="52" y="184" font-size="11.5" fill="#14532d">ilah edinilmesini emretmemiştir.</text>\n  <text x="42" y="208" font-size="11.5" font-weight="bold" fill="#15803d">• Çağrısı: "Rabbim ve Rabbiniz olan Allah\'a</text>\n  <text x="52" y="224" font-size="11.5" font-weight="bold" fill="#15803d">kulluk edin!" (Saf Tevhid İnancı)</text>\n  <!-- Sag: Tarihsel Degisim -->\n  <rect x="360" y="42" width="315" height="202" rx="10" fill="#fef2f2" stroke="#dc2626" stroke-width="2"/>\n  <text x="517" y="65" text-anchor="middle" font-size="13" font-weight="bold" fill="#991b1b">HZ. İSA SONRASI TARİHSEL DEĞİŞİMLER</text>\n  <text x="378" y="90" font-size="11.5" fill="#7f1d1d">• Pavlus\'un yorumlarıyla tevhid inancı yerine</text>\n  <text x="388" y="106" font-size="11.5" font-weight="bold" fill="#991b1b">Teslis (Baba - Oğul - Kutsal Ruh) benimsendi.</text>\n  <text x="378" y="128" font-size="11.5" fill="#7f1d1d">• MS 4. yüzyılda Roma\'nın resmî dini oldu.</text>\n  <text x="378" y="150" font-size="11.5" fill="#7f1d1d">• Konsillerde 4 İncil (Matta, Markos, Luka,</text>\n  <text x="388" y="166" font-size="11.5" fill="#7f1d1d">Yuhanna) resmî metin olarak seçildi.</text>\n  <rect x="378" y="182" width="280" height="48" rx="6" fill="#fee2e2"/>\n  <text x="518" y="202" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#7f1d1d">Barnaba İncili</text>\n  <text x="518" y="218" text-anchor="middle" font-size="11" fill="#991b1b">Hz. İsa\'nın kul ve peygamber olduğunu savundu.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
